function text(value) { return String(value == null ? '' : value).trim(); }
function norm(value) { return text(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); }
function bool(value) { return value === true || value === 1 || /^(true|1|yes|si)$/i.test(text(value)); }

function parseSerialized(value, fallback) {
  let current = value;
  for (let depth = 0; depth < 3; depth += 1) {
    if (typeof current !== 'string') break;
    const candidate = current.trim();
    if (!candidate || !/^[\[{\"]/.test(candidate)) break;
    try { current = JSON.parse(candidate); } catch { break; }
  }
  return current == null || current === '' ? fallback : current;
}

function normalizePatterns(value) {
  const parsed = parseSerialized(value, []);
  if (Array.isArray(parsed)) return parsed.map(text).filter(Boolean);
  return text(parsed).split('|').map(text).filter(Boolean);
}

function normalizeKbRow(row) {
  return {
    entry_key: text(row.entry_key),
    version: text(row.version || '1.0'),
    category: text(row.category),
    intent: norm(row.intent),
    question_patterns: normalizePatterns(row.question_patterns_json),
    answer_template: text(row.answer_template),
    allowed_claims: parseSerialized(row.allowed_claims_json, []),
    forbidden_claims: parseSerialized(row.forbidden_claims_json, []),
    requires_catalog: bool(row.requires_catalog),
    requires_human: bool(row.requires_human),
    active: bool(row.active),
  };
}

function normalizeObjectionRow(row) {
  return {
    objection_code: norm(row.objection_code),
    trigger_patterns: normalizePatterns(row.trigger_patterns_json),
    response_template: text(row.response_template),
    next_action: text(row.next_action),
    handoff_required: bool(row.handoff_required),
    active: bool(row.active),
    version: text(row.version || '1.0'),
  };
}

function versionScore(value) {
  return text(value).split('.').reduce((score, part, index) => score + (Number(part) || 0) * (1000 ** (2 - Math.min(index, 2))), 0);
}

function selectApprovedContent(input, kbRows, objectionRows) {
  const intent = norm(input && input.intent);
  const objectionCode = norm(input && input.objection_code);
  const userText = norm(input && input.user_message);
  const catalogReady = bool(input && input.catalog_ready);
  const kb = (kbRows || []).map(normalizeKbRow).filter((row) => row.active);
  const objections = (objectionRows || []).map(normalizeObjectionRow).filter((row) => row.active);
  const objection = objections
    .filter((row) => row.objection_code === objectionCode || row.trigger_patterns.some((pattern) => userText.includes(norm(pattern))))
    .sort((a, b) => versionScore(b.version) - versionScore(a.version))[0];
  if (objection) {
    return {
      found: true,
      source: 'objection_rules',
      key: objection.objection_code,
      answer_template: objection.response_template,
      next_action: objection.next_action,
      requires_human: objection.handoff_required,
      requires_catalog: false,
      reason_code: 'OBJECTION_RULE_MATCH',
    };
  }
  const entry = kb
    .filter((row) => row.intent === intent || row.question_patterns.some((pattern) => userText.includes(norm(pattern))))
    .sort((a, b) => versionScore(b.version) - versionScore(a.version))[0];
  if (!entry) return { found: false, source: 'fallback', key: '', answer_template: '', requires_human: false, requires_catalog: false, reason_code: 'KB_NO_APPROVED_ANSWER' };
  if (entry.requires_catalog && !catalogReady) return { found: false, source: 'catalog_gate', key: entry.entry_key, answer_template: '', requires_human: false, requires_catalog: true, reason_code: 'KB_CATALOG_UNAVAILABLE' };
  return {
    found: true,
    source: 'kb_entries',
    key: entry.entry_key,
    answer_template: entry.answer_template,
    allowed_claims: entry.allowed_claims,
    forbidden_claims: entry.forbidden_claims,
    requires_human: entry.requires_human,
    requires_catalog: entry.requires_catalog,
    reason_code: 'KB_APPROVED_ANSWER',
  };
}


const input = $('01 Entrada | Consulta aprobada').first().json || {};
const kbRows = $('02 KB | Leer entradas activas').all().map((item) => item.json || {});
const objectionRows = $input.all().map((item) => item.json || {});
const result = selectApprovedContent(input, kbRows, objectionRows);
return [{ json: { ...result, source_version: String(input.source_version || '3.0'), environment: String(input.environment || 'staging') } }];
